function validate(input) {
  const [{ Orders = [] }] = input;
  const ids = new Set();
  for (const [id, product, quantity, date] of Orders) {
    if (id === null) return 'Every order needs an order_id.';
    if (ids.has(id)) return `order_id ${id} appears twice in Orders.`;
    ids.add(id);
    if (product === null) return `Order ${id} needs a product_id.`;
    if (quantity !== null && quantity < 1) return `Order ${id} needs a positive quantity.`;
    if (date === null || !/^\d{4}-\d{2}-\d{2}$/.test(date)) return `Order ${id} needs a purchase_date like 2020-01-31.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const small = size === 'small';
  const count = small ? Math.floor(rand() * 9) : 2000;
  const products = small ? 1 + Math.floor(rand() * 2) : 200;
  const firstYear = 2018 + Math.floor(rand() * 3);
  const span = small ? 2 + Math.floor(rand() * 2) : 5;
  const pad = n => String(n).padStart(2, '0');
  const Orders = [];
  for (let id = 1; id <= count; id++) {
    const year = firstYear + Math.floor(rand() * span);
    // Dates at the turn of the year test that grouping uses calendar years.
    const r = rand();
    const day = r < 0.15 ? '01-01' : r < 0.3 ? '12-31' : `${pad(1 + Math.floor(rand() * 12))}-${pad(1 + Math.floor(rand() * 28))}`;
    Orders.push([id, 1 + Math.floor(rand() * products), pick([1, 2, 3, 5, 10]), `${year}-${day}`]);
  }
  return [{ Orders }];
}
